#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u;
    int v;
    long long d;
} Edge;

static Edge edges[2002005];
static Edge temp_edges[2002005];

// Radix sort for sorting edges by distance 'd'
void radix_sort(Edge *a, Edge *b, int n) {
    for (int shift = 0; shift < 64; shift += 8) {
        int count[256] = {0};
        for (int i = 0; i < n; i++) {
            count[(a[i].d >> shift) & 0xFF]++;
        }
        int total = 0;
        int pref[256];
        for (int i = 0; i < 256; i++) {
            pref[i] = total;
            total += count[i];
        }
        for (int i = 0; i < n; i++) {
            b[pref[(a[i].d >> shift) & 0xFF]++] = a[i];
        }
        Edge *tmp = a;
        a = b;
        b = tmp;
    }
}

int dp[2005];
int next_dp[2005];
