    x[0] = 0;
    y[0] = 0;
    for (int i = 1; i <= n; i++) {
        if (scanf("%d %d", &x[i], &y[i]) != 2) return 0;
    }

    int m = 0;
    // Edges between palace (0) and tents (1..n)
    for (int i = 1; i <= n; i++) {
        long long dx = x[i] - x[0];
        long long dy = y[i] - y[0];
        edges[m].u = 0;
        edges[m].v = i;
        edges[m].d = dx * dx + dy * dy;
        m++;
    }

    // Edges between tents
    for (int i = 1; i <= n; i++) {
        for (int j = i + 1; j <= n; j++) {
            long long dx = x[i] - x[j];
            long long dy = y[i] - y[j];
            edges[m].u = i;
            edges[m].v = j;
            edges[m].d = dx * dx + dy * dy;
            m++;
        }
    }

    // Sort edges by distance ascending
    radix_sort(edges, temp_edges, m);

    for (int i = 0; i <= n; i++) {
        dp[i] = 0;
        next_dp[i] = 0;
    }

    int ans = 0;
    int i = 0;
    while (i < m) {
        int j = i;
        while (j < m && edges[j].d == edges[i].d) {
            j++;
        }

        // Process group of edges with the same distance
        for (int k = i; k < j; k++) {
            int u = edges[k].u;
            int v = edges[k].v;

            if (u == 0) {
                // Edge from Palace to tent v
                if (1 + dp[v] > ans) {
                    ans = 1 + dp[v];
                }
            } else {
                // Tent to tent
                if (1 + dp[v] > next_dp[u]) {
                    next_dp[u] = 1 + dp[v];
                }
                if (1 + dp[u] > next_dp[v]) {
                    next_dp[v] = 1 + dp[u];
                }
            }
        }

        // Apply DP updates
        for (int k = i; k < j; k++) {
            int u = edges[k].u;
            int v = edges[k].v;
            if (u != 0) {
                if (next_dp[u] > dp[u]) {
                    dp[u] = next_dp[u];
                }
            }
            if (next_dp[v] > dp[v]) {
                dp[v] = next_dp[v];
            }
        }

        i = j;
    }

    printf("%d\n", ans);

    return 0;
}
